// Exact path when permitted; otherwise a best-effort WorkManager fallback so a
// reminder still eventually fires instead of silently never being scheduled. The
// fallback is Doze/App-Standby-deferrable, unlike setExactAndAllowWhileIdle, so it
// may fire late.
fun schedule(context: Context, doseLogId: Int, triggerAtMillis: Long, title: String, text: String) {
    cancel(context, doseLogId)
    if (canScheduleExact(context)) {
        val alarmManager = context.getSystemService(AlarmManager::class.java)
        alarmManager.setExactAndAllowWhileIdle(
            AlarmManager.RTC_WAKEUP,
            triggerAtMillis,
            pendingIntent(context, doseLogId, title, text),
        )
    } else {
        val delayMillis = (triggerAtMillis - System.currentTimeMillis()).coerceAtLeast(0)
        val request = OneTimeWorkRequestBuilder<CoarseReminderWorker>()
            .setInitialDelay(delayMillis, TimeUnit.MILLISECONDS)
            .setInputData(
                workDataOf(
                    EXTRA_DOSE_LOG_ID to doseLogId,
                    EXTRA_TITLE to title,
                    EXTRA_TEXT to text,
                ),
            )
            .build()
        WorkManager.getInstance(context)
            .enqueueUniqueWork("dose_reminder_$doseLogId", ExistingWorkPolicy.REPLACE, request)
    }
}
